"""Distinct art directions and journeys, applied by build.py before fingerprinting."""
from pathlib import Path
import re
R=Path(__file__).parent
def read(p):return (R/p).read_text()
def write(p,s):(R/p).write_text(s)
def add(p,s):write(p,read(p)+'\n'+s)
def replace_section(s,pattern,new):return re.sub(pattern,new,s,flags=re.S)
# FORM A / editorial portfolio with persistent index and a navigable cover.
p='forma/index.html';s=read(p)
s=s.replace('forma<span class="brand-dot">®</span>','F<span class="brand-dot">/</span>')
s=s.replace('<h1>Espaços que fazem<br>sentido. <span class="serif italic">Para você.</span></h1>','<h1>O espaço<br>entre a ideia<br>e a <span>vida.</span></h1>')
s=s.replace('<span class="eyebrow">Arquitetura · Interiores · Essência</span>','<span class="eyebrow">FORMA / ESTÚDIO DE ARQUITETURA<br>PORTFÓLIO CONCEITUAL — VOL. 01</span>')
s=s.replace('<figure class="hero-image">','<div class="cover-index"><span>ESTUDO EM EXIBIÇÃO</span><strong id="cover-name">Casa Horizonte</strong><div class="cover-controls"><button id="cover-prev" aria-label="Estudo anterior">←</button><span id="cover-count" aria-live="polite">01 / 03</span><button id="cover-next" aria-label="Próximo estudo">→</button></div></div><figure class="hero-image">')
s=s.replace('<figcaption><span>01 / Casa Horizonte</span><span>Estudo conceitual · Residencial</span></figcaption>','<figcaption><span id="cover-caption">01 / Casa Horizonte</span><span>Ilustração autoral / Estudo conceitual</span></figcaption>')
s=s.replace('<div class="hero-bottom"><p>Entre a luz, a matéria e a sua história,<br>encontramos um jeito único de habitar.</p>','<div class="hero-bottom"><p>ARQUITETURA É RELAÇÃO.<br>ENTRE O QUE EXISTE E O QUE PODE SER.</p>')
s=s.replace('Um olhar.<br><span class="serif italic">Muitas possibilidades.</span>','Índice de<br><span class="serif italic">projetos.</span>')
s=s.replace('Vamos dar forma<br><span class="serif italic">à sua ideia?</span>','Qual espaço<br><span class="serif italic">você imagina?</span>')
write(p,s)
