add('forma/app.js','''
const covers=[['Casa Horizonte','../assets/architecture.svg','01 / Casa Horizonte'],['Refúgio urbano','../assets/interior.svg','02 / Refúgio urbano'],['Ateliê de encontros','../assets/interior.svg','03 / Ateliê de encontros']];let cover=0;function changeCover(delta){cover=(cover+delta+covers.length)%covers.length;const c=covers[cover];document.getElementById('cover-name').textContent=c[0];document.getElementById('cover-count').textContent=String(cover+1).padStart(2,'0')+' / 03';document.getElementById('cover-caption').textContent=c[2];const img=document.querySelector('.hero-image img');img.src=c[1];img.alt='Estudo conceitual: '+c[0]}document.getElementById('cover-prev').addEventListener('click',()=>changeCover(-1));document.getElementById('cover-next').addEventListener('click',()=>changeCover(1));
''')
# AURORA / playful personal discovery, three-step guided experience on first screen.
p='aurora/index.html';s=read(p)
start=s.index('<div class="quiz">');end=s.index('</div></div></div></section>',start)
# Replace old preference quiz with a clear 3-step journey; keep anchor as a lower invitation.
s=s[:start]+'''<div class="ritual-invitation"><span>✳</span><h3>O melhor ritual é o seu.</h3><p>Sem teste de pele. Sem diagnóstico. Só suas preferências de tempo, momento e textura.</p><a class="btn" href="#descobrir">Montar meu ritual ↑</a></div>'''+s[end+12:]
s=s.replace('<section class="hero">','<section class="hero" id="descobrir">')
s=s.replace('<span class="eyebrow">Um momento seu. Todos os dias.</span>','<span class="aurora-sticker">BEM-VINDA À SUA PAUSA ✳</span>')
s=s.replace('<h1>Menos passos.<br>Mais <span class="serif italic">cuidado.</span></h1>','<h1>Seu cuidado.<br><span class="serif italic">Do seu jeito.</span></h1>')
s=s.replace('<p class="lead">Uma pausa no excesso. Conheça uma coleção conceitual que transforma o cuidado diário em um ritual simples.</p>','<p class="lead">Não existe uma rotina igual à sua. Vamos descobrir um ritual que caiba no seu dia?</p>')
s=s.replace('<div class="actions"><a class="btn" href="#colecao">Explorar a coleção ↗</a><a class="text-link" href="#filosofia">Conheça a essência ↓</a></div>','''<div class="ritual-builder" aria-label="Monte seu ritual"><div class="builder-top"><span>SEU RITUAL EM 3 ESCOLHAS</span><span id="quiz-progress">01 / 03</span></div><div class="progress-track"><span id="progress-fill"></span></div><h2 id="quiz-question">Quanto tempo você quer reservar?</h2><div id="quiz-answers"></div><div class="builder-bottom"><button id="quiz-back" disabled>← Voltar</button><span>Preferências, não diagnóstico.</span></div><div id="guided-result" aria-live="polite" hidden></div></div>''')
s=s.replace('<a class="btn" href="#rotina">Descobrir meu ritual ↗</a>','<a class="btn" href="#descobrir">Meu ritual ✳</a>')
s=s.replace('Descobrir meu ritual','Meu ritual')
s=s.replace('<div class="hero-notes">','<div class="hero-notes" aria-label="Princípios da marca">')
s=s.replace('Três gestos, um ritual','ESCOLHA SUA PRÓXIMA TEXTURA').replace('Sua pele.<br><span class="serif italic">Seu tempo.</span>','Pequenos frascos.<br><span class="serif italic">Grandes pausas.</span>')
s=s.replace('<div class="hero-art">','<div class="hero-art"><span class="floating-flower" aria-hidden="true">✳</span>')
write(p,s)
# Old quiz nodes were replaced; remove old bindings and keep product details.
a=read('aurora/app.js');a=a[a.index('const products='):];write('aurora/app.js',a)
add('aurora/app.js','''
const questions=[{q:'Quanto tempo você quer reservar?',a:['Dois minutinhos','Cinco minutos','Sem olhar o relógio']},{q:'Quando vem a sua pausa?',a:['No começo do dia','Depois que o dia acaba','Quando der vontade']},{q:'Qual sensação combina com você?',a:['Leve e fresquinha','Macia e envolvente','Gosto de descobrir']}];let step=0;const choices=[];const answers=document.getElementById('quiz-answers'),result=document.getElementById('guided-result');function paintQuiz(){result.hidden=true;document.getElementById('quiz-question').hidden=false;answers.hidden=false;document.getElementById('quiz-question').textContent=questions[step].q;document.getElementById('quiz-progress').textContent='0'+(step+1)+' / 03';document.getElementById('progress-fill').style.width=((step+1)/3*100)+'%';document.getElementById('quiz-back').disabled=step===0;answers.replaceChildren();questions[step].a.forEach((text,i)=>{const b=document.createElement('button');b.textContent=text+' ↗';b.setAttribute('aria-pressed',String(choices[step]===i));b.addEventListener('click',()=>{choices[step]=i;if(step<2){step++;paintQuiz();document.getElementById('quiz-question').focus()}else showRitual()});answers.append(b)});document.getElementById('quiz-question').tabIndex=-1}function showRitual(){answers.hidden=true;document.getElementById('quiz-question').hidden=true;result.hidden=false;result.replaceChildren();const h=document.createElement('h3');h.textContent=choices[0]===0?'Seu ritual: pausa essencial.':'Seu ritual: tempo para sentir.';const p=document.createElement('p');p.textContent='Você escolheu: '+choices.map((v,i)=>questions[i].a[v].toLowerCase()).join(' · ')+'. Explore '+(choices[2]===1?'Toque de calma, o creme conceitual de textura envolvente.':'Começo leve, o gel conceitual de textura fresca.')+' Isto é uma experiência de marca, sem indicação dermatológica.';const a=document.createElement('a');a.href='#colecao';a.className='btn';a.textContent='Explorar minha coleção ↓';const reset=document.createElement('button');reset.textContent='Recomeçar';reset.className='quiz-restart';reset.addEventListener('click',()=>{step=0;choices.length=0;paintQuiz()});result.append(h,p,a,reset);document.getElementById('quiz-progress').textContent='FEITO ✳';document.getElementById('quiz-back').disabled=false}document.getElementById('quiz-back').addEventListener('click',()=>{if(!result.hidden){step=2;paintQuiz()}else if(step>0){step--;paintQuiz()}});paintQuiz();
''')
