# BRASA / loud neighborhood pizza shop, menu-first and persistent order tray.
p='brasa/index.html';s=read(p)
s=s.replace('<h1>A noite pede<br><span class="serif italic">uma boa pizza.</span></h1>','<h1>FOME DE<br><span class="serif italic">PIZZA?</span></h1>')
s=s.replace('<span class="eyebrow">Massa leve · Forno quente · Mesa cheia</span>','<span class="eyebrow">BORDINHA DOURADA. CONVERSA SOLTA.</span>')
s=s.replace('Uma massa feita com tempo.<br>Ingredientes escolhidos com cuidado.<br>E aquele último pedaço que vira disputa.','A turma escolhe o filme.<br>Você escolhe o sabor.<br>O último pedaço? A gente não se mete.')
s=s.replace('<span class="hero-stamp">Feita para<br><b>compartilhar.</b></span>','<span class="hero-stamp">8 FATIAS<br><b>ZERO CERIMÔNIA.</b></span>')
s=s.replace('Escolher meu sabor ↗','QUERO PIZZA ↓')
s=s.replace('<span class="pizza-tag">Boa companhia.<br><i>Melhor ainda.</i></span>','<span class="pizza-tag">PIZZA BOA<br><i>JUNTA GENTE.</i></span>')
s=s.replace('Escolha bem.<br><span class="serif italic">Repita sem culpa.</span>','TÁ NA MESA.<br><span class="serif italic">QUAL VAI SER?</span>')
s=s.replace('Montar meu pedido ↗','PEDIR PIZZA +')
s=s.replace('<main id="main">','<main id="main"><div class="pizza-announcement">ESSA CASA É FICTÍCIA. A VONTADE DE PIZZA, TALVEZ NÃO. ✳</div>')
s=s.replace('<dialog class="dialog" id="cart-dialog">','<div class="order-dock" aria-label="Atalhos e pedido"><a href="#cardapio">☷ <span>Cardápio</span></a><a href="#historia">✳ <span>A casa</span></a><button data-dialog="cart-dialog" class="dock-order"><span>VER PEDIDO <b id="dock-count">0</b></span><strong id="dock-total">R$ 0,00</strong><span>→</span></button></div><dialog class="dialog" id="cart-dialog">')
s=s.replace('Seu pedido.','O SEU PEDIDO.')
s=s.replace('Chama a turma.<br><span class="serif italic">O sabor a gente resolve.</span>','CHAMA A TURMA.<br><span class="serif italic">TEM PIZZA.</span>')
write(p,s)
add('brasa/app.js','''
function syncDock(){document.getElementById('dock-count').textContent=document.getElementById('cart-count').textContent;document.getElementById('dock-total').textContent=document.getElementById('cart-total').textContent}const dockObserver=new MutationObserver(syncDock);dockObserver.observe(document.getElementById('cart-count'),{childList:true,subtree:true,characterData:true});dockObserver.observe(document.getElementById('cart-total'),{childList:true,subtree:true,characterData:true});syncDock();
''')
